import{z as A,x as s,o as r,c as p,q as E,j as i,D as e,d as l,s as n,S as B,b as t}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"MAP-Neo 报告","description":"","frontmatter":{"title":"MAP-Neo 报告","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/map-neo-report.md","filePath":"llm/map-neo-report.md","lastUpdated":1791413859000}'),m={name:"llm/map-neo-report.md"};function d(h,a,M,D,c,C){const o=s("Mermaid");return r(),p("div",null,[a[2]||(a[2]=E('<h1 id="map-neo-报告" tabindex="-1">MAP-Neo 报告 <a class="header-anchor" href="#map-neo-报告" aria-label="Permalink to &quot;MAP-Neo 报告&quot;">​</a></h1><div class="epigraph"><p>Chinchilla 拟合在多样高质量语料、数据量到数 T 时偏平；我们给损失加一项 $-d\\log D$，用来指导 7B 的配比，而不是宣布推翻 Hoffmann 曲线。</p><footer>—— Zhang 等，MAP-Neo，arXiv:2405.19327</footer></div><p><a href="/llm/map-neo">MAP-Neo</a> 已经交代 7B/2B、4.5T Matrix、8192 与透明度主张。技术报告的后半才是可复现手册：Spark 清洗、OCR、数学 recalling、<strong>基础阶段约 3.73T + 衰减阶段约 0.78T</strong>、以及用 250M/460M/980M 拟合出来的 <strong>NEO Scaling Law</strong>。本篇写这些附录级选择，不重复系列定位。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>透明英语 7B（Pythia、Amber、<a href="/llm/olmo-paper">OLMo</a>）在 HumanEval、GSM8K、MMLU、C-EVAL 上仍明显落后工业开权重。MAP-Neo 要把双语、代码与数学拉到可引用对照，必须回答两件 Chinchilla 回答不了的事：异构语料上损失随 \\(D\\) 的形状，以及「基础阶段学通顺、衰减阶段补代码」会不会把已经学到的中文知识冲掉。</p><p>分词器是另一条事故链。SentencePiece 默认 <code>remove extra whitespaces=True</code> 会把缩进塌成单空格。基础阶段若没关，推理与数学仍可涨、代码指标抖动——这不是宽度能补的。报告把修复放在衰减阶段换固定版词表，而不是推倒重来 4.5T。</p><h3 id="matrix-网页过半、代码约两成、中英分桶去重" tabindex="-1">Matrix：网页过半、代码约两成、中英分桶去重 <a class="header-anchor" href="#matrix-网页过半、代码约两成、中英分桶去重" aria-label="Permalink to &quot;Matrix：网页过半、代码约两成、中英分桶去重&quot;">​</a></h3><p>Matrix 发布时自称最大的透明预训练堆之一（约 4.5T / 卡片写 4690B token）。英语侧是对 RedPajama-V2、Dolma CC、CulturaX、Amber/RefinedWeb、SlimPajama 等的再过滤：精确文档去重、MinHash LSH、段落与超长子串。因内存不够，Spark 把文本分桶再逐桶去重。中文约 80% 自爬，其余 CCI、ChineseWebText、万卷、Yayi、SkyPile；Spark 难部署时改用 Bloom Filter（假阳率 0.001）做精确去重。另有印刷品 OCR：Pix2Text/TrOCR 公式、PP-OCRv4 文字、SLANet 表；页眉页脚丢弃。主题召回跟 DeepSeek-Math 式 recalling，从网页里把高教育价值域捞回来。</p><p><span class="marginnote">MinHash 与 \\(k=50\\) 子串会误删法律条款、许可证头一类合法重复。Bloom Filter 假阳会丢掉本应保留的中文页。透明的是阈值与代码，不是「零误删」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="两阶段-3726b-余弦-再-778b-指数衰减" tabindex="-1">两阶段：3726B 余弦，再 778B 指数衰减 <a class="header-anchor" href="#两阶段-3726b-余弦-再-778b-指数衰减" aria-label="Permalink to &quot;两阶段：3726B 余弦，再 778B 指数衰减&quot;">​</a></h3><p>基础阶段：学习率从 \\(2\\times 10^{-5}\\) 线性升到 \\(2\\times 10^{-4}\\)（2k 步），再余弦回到 \\(2\\times 10^{-5}\\)（约 365k 步），处理约 <strong>3726B</strong> token。代码当时用 Stack V1 并重复两次以凑配比。衰减阶段：学习率从 \\(2\\times 10^{-4}\\) 指数衰减约 148k 步（半衰期为衰减步数的一半，写法对齐 MiniCPM），约 <strong>778B</strong> token，提高书籍、裁判文书、政府文件与指令风格密度；代码换成 Stack V2，代码占比从约 14.77% 提到约 17.04%。7B 在 64 节点 512 张 H800 上训，张量并行 2；他们改 Megatron 以处理超大语料溢出，并做坏节点隔离。</p><p><span class="marginnote">直觉类比：基础阶段像把所有科目的课本通读一遍求「广」，衰减阶段像考前用高质量真题收尾——778B 只占总量的约 17%，却决定最后成绩的形状。MAP-Neo 在这一段顺手把代码教材换成了修订版（Stack V2），并加大了代码的课时占比。</span></p><p>对齐：SFT 两段——先 200 万+ 指令（OpenHermes 2.5 去 TheoremQA、Code-Feedback、WebInstructSub 子集）3 个 epoch 打基础，再 10 万+ 真实多轮加 5k 数学代码回放 1 个 epoch 打聊天。然后迭代 DPO（Nectar 提示、Starling-RM-34B，第三轮加中文偏好）。序列 8192，batch 512。</p> \\[L(N,D)=\\frac{A}{N^{\\alpha}}+\\frac{B}{D^{\\beta}}+E-d\\cdot\\log D \\]<p>NEO 律在 Chinchilla 三项后再减 \\(d\\log D\\)。代理模型 250M/460M/980M 各吃 1000B，用来外推 7.8B 在 phase-1 的 <strong>3.07T</strong>。\\(d\\) 实验里大约 \\(10^{-2}\\) 到 \\(3\\times 10^{-2}\\)；作者承认 \\(D\\to\\infty\\) 时公式无下界，只在「数 T 到百 T 以下」当局部修正。Huber \\(\\delta=10^{-3}\\) 与 \\(R^2\\) 显示比纯 Chinchilla 更贴实际损失——多样语料在 \\(D\\) 大时掉点比 \\(B/D^{\\beta}\\) 更快。</p><p><span class="marginnote">术语翻译：\\(-d\\log D\\) 是给 Chinchilla 损失加的一个「数据越多、掉点越快」的小修正项，\\(d\\) 只有 \\(10^{-2}\\) 量级。原公式说损失随数据按幂律缓慢下降；这项用来描述多样高质量语料在数 T 量级上的额外红利。它是局部拐杖，不是新物理定律——\\(D\\) 极大时公式会失去下界。</span></p>',17)),(r(),i(B,null,{default:e(()=>[n(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20EN%5B%22%E8%8B%B1%E8%AF%AD%E5%BC%80%E6%BA%90%E5%A0%86%20Spark%20%E5%88%86%E6%A1%B6%E5%8E%BB%E9%87%8D%22%5D%20--%3E%20MX%5B%22Matrix%204.5T%22%5D%0A%20%20ZH%5B%22%E4%B8%AD%E6%96%87%E8%87%AA%E7%88%AC%20%2B%20Bloom%20%E5%8E%BB%E9%87%8D%22%5D%20--%3E%20MX%0A%20%20OCR%5B%22%E5%8D%B0%E5%88%B7%E5%93%81%20OCR%22%5D%20--%3E%20MX%0A%20%20REC%5B%22%E5%9F%9F%E5%8F%AC%E5%9B%9E%20%2F%20%E6%95%B0%E5%AD%A6%20recalling%22%5D%20--%3E%20MX%0A%20%20MX%20--%3E%20P1%5B%22%E5%9F%BA%E7%A1%80%203.73T%20%E4%BD%99%E5%BC%A6%22%5D%0A%20%20P1%20--%3E%20P2%5B%22%E8%A1%B0%E5%87%8F%200.78T%EF%BC%9A%E4%BF%AE%E8%AF%8D%E8%A1%A8%E7%A9%BA%E7%99%BD%20%2B%20%E6%8F%90%E4%BB%A3%E7%A0%81%22%5D%0A%20%20P2%20--%3E%20SFT%5B%22%E4%B8%A4%E6%AE%B5%20SFT%22%5D%0A%20%20SFT%20--%3E%20DPO%5B%22%E8%BF%AD%E4%BB%A3%20DPO%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[l("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"NEO 项的机制主张很窄：异构、高质量、可召回的混合，使大 \\(D\\) 时损失比网页堆的 Chinchilla 拟合更陡。它解释的是这条 Matrix 配比，用来决定 7B 该吃多少、衰减段要不要加代码，而不是一条新物理定律。对 DeepSeek-67B 一类公开曲线，作者说 Chinchilla 会在 \\(D\\) 小时低估损失、\\(N\\) 与 \\(D\\) 都大时高估；NEO 更贴。不要外推到任意 MoE 或纯代码语料。",-1)),a[5]||(a[5]=t("p",null,"词表空白开关是机制级事故：代码缩进是语法。基础阶段 QA 与数学仍可涨，说明那些任务不依赖空格；HumanEval 依赖。衰减段换 Stack V2 并提高代码比，是在已经修好的 token 上让表示进盆地，不是突然多了一层 MLP。中文网页召回同样走数据轴。",-1)),(r(),i(B,null,{default:e(()=>[n(o,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20SP%5B%22SentencePiece%20%E9%BB%98%E8%AE%A4%E5%8E%BB%E5%A4%9A%E4%BD%99%E7%A9%BA%E7%99%BD%22%5D%20--%3E%20COL%5B%22%E7%BC%A9%E8%BF%9B%E5%A1%8C%E6%88%90%E5%8D%95%E7%A9%BA%E6%A0%BC%22%5D%0A%20%20COL%20--%3E%20CODE%5B%22%E4%BB%A3%E7%A0%81%E4%BB%BB%E5%8A%A1%EF%BC%9A%E7%BC%A9%E8%BF%9B%E5%8D%B3%E8%AF%AD%E6%B3%95%EF%BC%8CHumanEval%20%E6%8A%96%E5%8A%A8%22%5D%0A%20%20COL%20--%3E%20NLC%5B%22QA%20%2F%20%E6%95%B0%E5%AD%A6%EF%BC%9A%E4%B8%8D%E4%BE%9D%E8%B5%96%E7%A9%BA%E6%A0%BC%EF%BC%8C%E6%8C%87%E6%A0%87%E7%85%A7%E5%B8%B8%E6%B6%A8%22%5D%0A%20%20NLC%20--%3E%20HIDE%5B%22%E4%BA%8B%E6%95%85%E5%9C%A8%E5%9F%BA%E7%A1%80%E9%98%B6%E6%AE%B5%E4%B8%8D%E6%98%93%E5%AF%9F%E8%A7%89%22%5D%0A%20%20HIDE%20--%3E%20FIX%5B%22%E8%A1%B0%E5%87%8F%E9%98%B6%E6%AE%B5%E6%8D%A2%E5%9B%BA%E5%AE%9A%E8%AF%8D%E8%A1%A8%20%2B%20Stack%20V2%22%5D%0A%20%20CODE%20--%3E%20FIX%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<p><span class="marginnote">常见误区：以为词表出问题会「全线崩溃」。实际相反——QA、数学这类不依赖缩进的任务照常上涨，只有代码指标抖动，事故最隐蔽的形态就是「大部分指标看起来正常」。开训前用一小段代码文本检查空白是否保留，成本几乎为零。</span></p><p><span class="marginnote">报告 Table 1 自比：MAP-Neo-7B 在 C-EVAL / MMLU / GSM8K / HumanEval 上高于所列透明模型，并在部分项接近 Llama 3 8B / Mistral。这是他们统一评测管线，转引要写协议。MMLU 58 对 OLMo 53 是同一张表里的数，不是跨论文拼接。</span></p><h3 id="基础设施不是聊天模型卡" tabindex="-1">基础设施不是聊天模型卡 <a class="header-anchor" href="#基础设施不是聊天模型卡" aria-label="Permalink to &quot;基础设施不是聊天模型卡&quot;">​</a></h3><p>H800、NCCL、IB、NVSwitch 与双层 Clos 是 512 卡作业跑完的条件。透明的一半是 Matrix，另一半是 Megatron 溢出补丁与坏节点隔离。别人用上游 Megatron 重训同一堆，会在他们修过的边界上失败。迭代 DPO 用的 Starling / Yi 奖励模型把另一条模型的偏好带进来：透明度在「用了哪份 RM」上是开的，在 RM 自身数据上并不开。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>4.5T 的存储与清洗需要集群。OCR 错误会进下一词。衰减段 778B 含指令风格数据，和「纯预训练」口径不同，对比 OLMo 的 2.46T 网页时要声明。2B 为 MQA、7B 满头，不能同一套 KV 配置。从别的 7B 词表热启会错位。NEO 公式在 \\(D\\) 极大时理论无下界，不能当外推到 100T 的许可证。</p><p>「第一个性能可比的全开源双语 LLM」是 2024 年中的自我定位，对照透明英语模型与部分开权重 7B，不要扩写成超过所有 2025 年开源 7B。衰减段 778B 里指令风格数据会让「纯预训练底座」与 OLMo 的 2.46T 网页不好直接比损失；要比就声明阶段。SFT 第二段只加 5k 数学代码回放，是怕聊天数据把 HumanEval 冲掉——这是配比护栏，不是新对齐算法。从别的 7B 词表热启会在空白与数字切分上同时错位，检查点也接不上他们 Megatron 改过的溢出边界。NEO 律的代理模型只吃 1000B，用来外推 7B 的 3T 级 phase-1；把代理损失直接当成 7B 的 MMLU 预测会跳过「能力不等于损失」这一层。</p><p><span class="marginnote">仓库 <code>multimodal-art-projection/MAP-NEO</code>；语料 <code>m-a-p/Matrix</code>。v4 于 2024-07。缩放律代理检查点（250M/460M/980M）与 7B 不是同一条产品线，不要把代理 MMLU 当成 7B。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>报告把 4.5T 拆成基础约 3.73T 与衰减约 0.78T；衰减段修词表空白、换 Stack V2、提高代码与高质量回放。</li><li>Matrix 的英语走 Spark 分桶去重，中文常用 Bloom Filter；另含 OCR 与域召回。</li><li>NEO Scaling Law 为 Chinchilla 加 \\(-d\\log D\\)，用 250M–980M 拟合指导 7B，适用窗口是数 T 级多样语料。</li><li>对齐为两段 SFT 加迭代 DPO；训练栈含改过的 Megatron。</li><li>出处：Zhang 等，<em>MAP-Neo: Highly Capable and Transparent Bilingual Large Language Model Series</em>，arXiv:2405.19327，2024。</li></ul>',10))])}const g=A(m,[["render",d]]);export{P as __pageData,g as default};
